    right_cars = [i for i in range(n, 2*n)]  # Initialize positions of cars moving right to left

    collision_count = 0

    for left_car in left_cars:
        for right_car in right_cars:
            if left_car == right_car:  # Check for potential collision point
                collision_count += 1  # Increment collision count

    return collision_count

