import math

def triangle_area(a, b, c):
    # Check if the sum of any two sides is greater than the third side to determine if it's a valid triangle
    if a + b > c and a + c > b and b + c > a:
        # Calculate the semi-perimeter by adding all three sides and dividing by 2
        s = (a + b + c) / 2
        # Calculate the area using Heron's formula
        area = math.sqrt(s * (s - a) * (s - b) * (s - c))
        # Round the area to 2 decimal points
        return round(area, 2)
    else:
        return -1

